// Des: App state in SQLite: caps counters, keys, ledger, log
// Flo: open db (WAL) > migrate > count acts > take or finish idempotency key > ledger rows > log rows
// I/O: SQL via st-stor-sqli (caller paths) > counts, keys, ledger rows, log rows (db file in state dir)
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig");
const MIGS = [_][:0]const u8{ "CREATE TABLE meta(k TEXT PRIMARY KEY, v INTEGER NOT NULL);CREATE TABLE acts(id INTEGER PRIMARY KEY, ts INTEGER NOT NULL, kind TEXT NOT NULL, targ TEXT NOT NULL);CREATE INDEX acts_kind ON acts(kind, ts);CREATE TABLE keyz(k TEXT PRIMARY KEY, st TEXT NOT NULL, ts INTEGER NOT NULL);CREATE TABLE ledg(id INTEGER PRIMARY KEY, lid TEXT NOT NULL, titl TEXT NOT NULL, grou TEXT NOT NULL, pms INTEGER NOT NULL, st TEXT NOT NULL, ums INTEGER NOT NULL);CREATE TABLE logz(id INTEGER PRIMARY KEY, ts INTEGER NOT NULL, kind TEXT NOT NULL, what TEXT NOT NULL, ok INTEGER NOT NULL);CREATE TABLE know(targ TEXT PRIMARY KEY, ts INTEGER NOT NULL);", "CREATE TABLE flowz(id INTEGER PRIMARY KEY, name TEXT NOT NULL, st TEXT NOT NULL, ts INTEGER NOT NULL, ivn INTEGER NOT NULL, wms INTEGER NOT NULL);CREATE TABLE flowq(id INTEGER PRIMARY KEY, fid INTEGER NOT NULL, seq INTEGER NOT NULL, job TEXT NOT NULL, args TEXT NOT NULL, st TEXT NOT NULL, appr INTEGER NOT NULL, info TEXT NOT NULL, ts INTEGER NOT NULL);CREATE INDEX flowq_fid ON flowq(fid, seq);", "CREATE TABLE mapz(id INTEGER PRIMARY KEY, path TEXT NOT NULL, role TEXT NOT NULL, name TEXT NOT NULL, ts INTEGER NOT NULL);CREATE INDEX mapz_path ON mapz(path);" };
pub const Item = struct { id: i64, fid: i64, seq: i64, job: []const u8, args: []const u8, st: []const u8, appr: i64, info: []const u8 };
pub const Flow = struct { id: i64, name: []const u8, st: []const u8, ts: i64, ivn: i64, wms: i64 };
const CF = .{ .pend = "pend", .done = "done" };
pub const Take = enum { go, dupe, unsure };
pub const Ledg = struct { id: i64, lid: []const u8, titl: []const u8, grou: []const u8, pms: i64, st: []const u8, ums: i64 };
pub const Logr = struct { ts: i64, kind: []const u8, what: []const u8, ok: bool };
pub const Stat = struct { db: sqli.Db,
pub fn open(allo: std.mem.Allocator, path: [:0]const u8) !Stat { var dbzz = try sqli.Db.open(path); errdefer dbzz.close(); try dbzz.migr(allo, &MIGS); return .{ .db = dbzz }; }
pub fn close(self: *Stat) void { self.db.close(); }
pub fn bornGet(self: *Stat, now: i64) !i64 { var sel = try self.db.prep("SELECT v FROM meta WHERE k='born';"); defer sel.fini(); if (try sel.step()) return sel.colInt(0); var ins = try self.db.prep("INSERT INTO meta(k,v) VALUES('born',?1);"); defer ins.fini(); try ins.bindInt(1, now); _ = try ins.step(); return now; }
pub fn flagGet(self: *Stat, name: [:0]const u8) !bool { var sel = try self.db.prep("SELECT v FROM meta WHERE k=?1;"); defer sel.fini(); try sel.bindText(1, name); if (try sel.step()) return sel.colInt(0) != 0; return false; }
pub fn flagSet(self: *Stat, name: []const u8, on: bool) !void { var ins = try self.db.prep("INSERT INTO meta(k,v) VALUES(?1,?2) ON CONFLICT(k) DO UPDATE SET v=excluded.v;"); defer ins.fini(); try ins.bindText(1, name); try ins.bindInt(2, if (on) 1 else 0); _ = try ins.step(); }
pub fn actAdd(self: *Stat, kind: []const u8, targ: []const u8, now: i64) !void { var ins = try self.db.prep("INSERT INTO acts(ts,kind,targ) VALUES(?1,?2,?3);"); defer ins.fini(); try ins.bindInt(1, now); try ins.bindText(2, kind); try ins.bindText(3, targ); _ = try ins.step(); }
pub fn actCnt(self: *Stat, kind: []const u8, since: i64) !i64 { var sel = try self.db.prep("SELECT COUNT(*) FROM acts WHERE kind=?1 AND ts>=?2;"); defer sel.fini(); try sel.bindText(1, kind); try sel.bindInt(2, since); if (try sel.step()) return sel.colInt(0); return 0; }
pub fn keyTake(self: *Stat, key: []const u8, now: i64) !Take { var sel = try self.db.prep("SELECT st FROM keyz WHERE k=?1;"); defer sel.fini(); try sel.bindText(1, key); if (try sel.step()) { return if (std.mem.eql(u8, sel.colText(0), CF.done)) .dupe else .unsure; } var ins = try self.db.prep("INSERT INTO keyz(k,st,ts) VALUES(?1,'pend',?2);"); defer ins.fini(); try ins.bindText(1, key); try ins.bindInt(2, now); _ = try ins.step(); return .go; }
pub fn keyDone(self: *Stat, key: []const u8, now: i64) !void { var upd = try self.db.prep("UPDATE keyz SET st='done', ts=?2 WHERE k=?1;"); defer upd.fini(); try upd.bindText(1, key); try upd.bindInt(2, now); _ = try upd.step(); }
pub fn keyDrop(self: *Stat, key: []const u8) !void { var del = try self.db.prep("DELETE FROM keyz WHERE k=?1 AND st='pend';"); defer del.fini(); try del.bindText(1, key); _ = try del.step(); }
pub fn ledgAdd(self: *Stat, lid: []const u8, titl: []const u8, grou: []const u8, now: i64) !i64 { var ins = try self.db.prep("INSERT INTO ledg(lid,titl,grou,pms,st,ums) VALUES(?1,?2,?3,?4,'live',?4);"); defer ins.fini(); try ins.bindText(1, lid); try ins.bindText(2, titl); try ins.bindText(3, grou); try ins.bindInt(4, now); _ = try ins.step(); return self.db.lastRow(); }
pub fn ledgSet(self: *Stat, titl: []const u8, st: []const u8, now: i64) !i64 { var upd = try self.db.prep("UPDATE ledg SET st=?2, ums=?3 WHERE titl=?1 AND st<>'sold';"); defer upd.fini(); try upd.bindText(1, titl); try upd.bindText(2, st); try upd.bindInt(3, now); _ = try upd.step(); return self.db.changes(); }
pub fn ledgReset(self: *Stat, titl: []const u8, st: []const u8, now: i64) !i64 { var upd = try self.db.prep("UPDATE ledg SET st=?2, ums=?3 WHERE titl=?1;"); defer upd.fini(); try upd.bindText(1, titl); try upd.bindText(2, st); try upd.bindInt(3, now); _ = try upd.step(); return self.db.changes(); }
pub fn ledgList(self: *Stat, aren: std.mem.Allocator) ![]Ledg { var sel = try self.db.prep("SELECT id,lid,titl,grou,pms,st,ums FROM ledg ORDER BY id;"); defer sel.fini(); var out: std.ArrayList(Ledg) = .empty; while (try sel.step()) try out.append(aren, .{ .id = sel.colInt(0), .lid = try aren.dupe(u8, sel.colText(1)), .titl = try aren.dupe(u8, sel.colText(2)), .grou = try aren.dupe(u8, sel.colText(3)), .pms = sel.colInt(4), .st = try aren.dupe(u8, sel.colText(5)), .ums = sel.colInt(6) }); return out.items; }
pub fn logAdd(self: *Stat, kind: []const u8, what: []const u8, ok: bool, now: i64) !void { var ins = try self.db.prep("INSERT INTO logz(ts,kind,what,ok) VALUES(?1,?2,?3,?4);"); defer ins.fini(); try ins.bindInt(1, now); try ins.bindText(2, kind); try ins.bindText(3, what); try ins.bindInt(4, if (ok) 1 else 0); _ = try ins.step(); }
pub fn logRecent(self: *Stat, aren: std.mem.Allocator, cnt: u32) ![]Logr { var sel = try self.db.prep("SELECT ts,kind,what,ok FROM logz ORDER BY id DESC LIMIT ?1;"); defer sel.fini(); try sel.bindInt(1, cnt); var out: std.ArrayList(Logr) = .empty; while (try sel.step()) try out.append(aren, .{ .ts = sel.colInt(0), .kind = try aren.dupe(u8, sel.colText(1)), .what = try aren.dupe(u8, sel.colText(2)), .ok = sel.colInt(3) != 0 }); return out.items; }
pub fn knowHas(self: *Stat, targ: []const u8) !bool { var sel = try self.db.prep("SELECT 1 FROM know WHERE targ=?1;"); defer sel.fini(); try sel.bindText(1, targ); return try sel.step(); }
pub fn knowAdd(self: *Stat, targ: []const u8, now: i64) !void { var ins = try self.db.prep("INSERT OR IGNORE INTO know(targ,ts) VALUES(?1,?2);"); defer ins.fini(); try ins.bindText(1, targ); try ins.bindInt(2, now); _ = try ins.step(); }
pub fn metaGet(self: *Stat, name: []const u8) !i64 { var sel = try self.db.prep("SELECT v FROM meta WHERE k=?1;"); defer sel.fini(); try sel.bindText(1, name); if (try sel.step()) return sel.colInt(0); return 0; }
pub fn metaSet(self: *Stat, name: []const u8, val: i64) !void { var ins = try self.db.prep("INSERT INTO meta(k,v) VALUES(?1,?2) ON CONFLICT(k) DO UPDATE SET v=excluded.v;"); defer ins.fini(); try ins.bindText(1, name); try ins.bindInt(2, val); _ = try ins.step(); }
pub fn ledgGroup(self: *Stat, titl: []const u8, grou: []const u8) !i64 { var upd = try self.db.prep("UPDATE ledg SET grou=CASE WHEN grou='' THEN ?2 ELSE grou||'; '||?2 END WHERE titl=?1;"); defer upd.fini(); try upd.bindText(1, titl); try upd.bindText(2, grou); _ = try upd.step(); return self.db.changes(); }
pub fn logPurge(self: *Stat, before: i64) !i64 { var del = try self.db.prep("DELETE FROM logz WHERE ts<?1;"); defer del.fini(); try del.bindInt(1, before); _ = try del.step(); return self.db.changes(); }
pub fn actPurge(self: *Stat, before: i64) !i64 { var del = try self.db.prep("DELETE FROM acts WHERE ts<?1;"); defer del.fini(); try del.bindInt(1, before); _ = try del.step(); return self.db.changes(); }
pub fn mapClear(self: *Stat, path: []const u8) !void { var del = try self.db.prep("DELETE FROM mapz WHERE path=?1;"); defer del.fini(); try del.bindText(1, path); _ = try del.step(); }
pub fn mapAdd(self: *Stat, path: []const u8, role: []const u8, name: []const u8, now: i64) !void { var ins = try self.db.prep("INSERT INTO mapz(path,role,name,ts) VALUES(?1,?2,?3,?4);"); defer ins.fini(); try ins.bindText(1, path); try ins.bindText(2, role); try ins.bindText(3, name); try ins.bindInt(4, now); _ = try ins.step(); }
pub fn mapCount(self: *Stat, path: []const u8) !i64 { var sel = try self.db.prep("SELECT COUNT(*) FROM mapz WHERE path=?1;"); defer sel.fini(); try sel.bindText(1, path); if (!try sel.step()) return 0; return sel.colInt(0); }
pub fn flowNew(self: *Stat, name: []const u8, now: i64) !i64 { var ins = try self.db.prep("INSERT INTO flowz(name,st,ts,ivn,wms) VALUES(?1,'run',?2,0,0);"); defer ins.fini(); try ins.bindText(1, name); try ins.bindInt(2, now); _ = try ins.step(); return self.db.lastRow(); }
pub fn flowSet(self: *Stat, fid: i64, st: []const u8) !void { var upd = try self.db.prep("UPDATE flowz SET st=?2 WHERE id=?1;"); defer upd.fini(); try upd.bindInt(1, fid); try upd.bindText(2, st); _ = try upd.step(); }
pub fn flowBump(self: *Stat, fid: i64, ivn: i64, wms: i64) !void { var upd = try self.db.prep("UPDATE flowz SET ivn=ivn+?2, wms=wms+?3 WHERE id=?1;"); defer upd.fini(); try upd.bindInt(1, fid); try upd.bindInt(2, ivn); try upd.bindInt(3, wms); _ = try upd.step(); }
pub fn flowGet(self: *Stat, aren: std.mem.Allocator, fid: i64) !?Flow { var sel = try self.db.prep("SELECT id,name,st,ts,ivn,wms FROM flowz WHERE id=?1;"); defer sel.fini(); try sel.bindInt(1, fid); if (!try sel.step()) return null; return .{ .id = sel.colInt(0), .name = try aren.dupe(u8, sel.colText(1)), .st = try aren.dupe(u8, sel.colText(2)), .ts = sel.colInt(3), .ivn = sel.colInt(4), .wms = sel.colInt(5) }; }
pub fn flowOpen(self: *Stat) !i64 { var sel = try self.db.prep("SELECT id FROM flowz WHERE st IN ('run','wait','plan') ORDER BY id DESC LIMIT 1;"); defer sel.fini(); if (try sel.step()) return sel.colInt(0); return 0; }
pub fn flowLast(self: *Stat) !i64 { var sel = try self.db.prep("SELECT id FROM flowz ORDER BY id DESC LIMIT 1;"); defer sel.fini(); if (try sel.step()) return sel.colInt(0); return 0; }
pub fn itemAdd(self: *Stat, fid: i64, seq: i64, job: []const u8, args: []const u8, appr: i64, now: i64) !void { var ins = try self.db.prep("INSERT INTO flowq(fid,seq,job,args,st,appr,info,ts) VALUES(?1,?2,?3,?4,'todo',?5,'',?6);"); defer ins.fini(); try ins.bindInt(1, fid); try ins.bindInt(2, seq); try ins.bindText(3, job); try ins.bindText(4, args); try ins.bindInt(5, appr); try ins.bindInt(6, now); _ = try ins.step(); }
pub fn itemList(self: *Stat, aren: std.mem.Allocator, fid: i64) ![]Item { var sel = try self.db.prep("SELECT id,fid,seq,job,args,st,appr,info FROM flowq WHERE fid=?1 ORDER BY seq;"); defer sel.fini(); try sel.bindInt(1, fid); var out: std.ArrayList(Item) = .empty; while (try sel.step()) try out.append(aren, .{ .id = sel.colInt(0), .fid = sel.colInt(1), .seq = sel.colInt(2), .job = try aren.dupe(u8, sel.colText(3)), .args = try aren.dupe(u8, sel.colText(4)), .st = try aren.dupe(u8, sel.colText(5)), .appr = sel.colInt(6), .info = try aren.dupe(u8, sel.colText(7)) }); return out.items; }
pub fn itemSet(self: *Stat, id: i64, st: []const u8, info: []const u8, now: i64) !void { var upd = try self.db.prep("UPDATE flowq SET st=?2, info=?3, ts=?4 WHERE id=?1;"); defer upd.fini(); try upd.bindInt(1, id); try upd.bindText(2, st); try upd.bindText(3, info); try upd.bindInt(4, now); _ = try upd.step(); }
pub fn itemAppr(self: *Stat, fid: i64, seq: i64, val: i64) !i64 { var upd = try self.db.prep("UPDATE flowq SET appr=?3 WHERE fid=?1 AND (?2<0 OR seq=?2) AND appr=0;"); defer upd.fini(); try upd.bindInt(1, fid); try upd.bindInt(2, seq); try upd.bindInt(3, val); _ = try upd.step(); return self.db.changes(); } };
